declare(strict_types=1);require __DIR__.'/config/bootstrap.php';require __DIR__.'/lib/MaketouClient.php';$num=(string)($_GET['order']??'');$message='Commande introuvable';$ok=false;if($num!==''){try{$pdo=db();$q=$pdo->prepare('SELECT o.*,p.name product FROM orders o JOIN products p ON p.id=o.product_id WHERE o.order_number=? LIMIT 1');$q->execute([$num]);$o=$q->fetch();if($o){$m=new MaketouClient((string)config('maketou.api_key'));$cart=$m->cart((string)$o['maketou_reference']);$status=$cart['status']??'';$map=['completed'=>'paid','payment_failed'=>'failed','abandoned'=>'cancelled'];if(isset($map[$status])){$pdo->prepare('UPDATE orders SET payment_status=? WHERE id=? AND payment_status="pending"')->execute([$map[$status],$o['id']]);}$ok=$status==='completed';$message=$ok?'Paiement confirmé. Votre commande est en cours de traitement.':'Paiement : '.($status?:'inconnu');}}catch(Throwable $e){$message='Impossible de vérifier le paiement pour le moment.';}}?><!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SOMBA — Paiement</title><body style="font-family:Arial;background:#080b14;color:#fff;display:grid;place-items:center;min-height:100vh"><main style="max-width:600px;text-align:center;padding:30px"><h1>SOMBA</h1><h2><?=htmlspecialchars($message)?></h2><p><?=htmlspecialchars($num)?></p><a href="/" style="color:#25d9ff">Retour à la boutique</a></main></body></html>
